// 에스컬레이션 단계별로 분류한다.
// BHC-STD §10.3 — E1 담당자 / E2 대표 서면 / E3 S6 계상·RF-7 / E4 관계기관
// P0는 24시간 기준이라 기한 초과가 아니어도 착수 지연만으로 E2·E4가 발동한다.
const LEVEL_RANK = { E1: 1, E2: 2, E3: 3, E4: 4 };
const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const rows = (d.prescriptions || []).filter(r => r.escalation || r.days_overdue > 0);
  if (!rows.length) continue;

  const worst = rows.reduce((a, r) => {
    const lv = r.escalation?.level ?? 'E1';
    return LEVEL_RANK[lv] > LEVEL_RANK[a] ? lv : a;
  }, 'E1');

  out.push({
    json: {
      building_id: d.building_id,
      worst_level: worst,
      total: rows.length,
      p0: rows.filter(r => r.priority === 'P0').length,
      overdue_max: Math.max(...rows.map(r => r.days_overdue || 0)),
      rows: rows.slice(0, 12),
      metrics: d.metrics,
    },
  });
}
return out;

// 발송 문안 — 파일·수치만 던지지 않는다.
// (1) 무엇이 몇 건인지 (2) 핵심 수치 (3) 유의점 (4) 무엇부터 볼지
const URGENT = new Set(['E3', 'E4']);
return $input.all().map(i => {
  const d = i.json;
  const head = URGENT.has(d.worst_level) ? ':rotating_light:' : ':warning:';
  const lines = [
    `${head} *CAPA 에스컬레이션 — 시설물 #${d.building_id}*`,
    `• 대상 처방 ${d.total}건 · P0 ${d.p0}건 · 최대 기한초과 ${d.overdue_max}일`,
    `• 최고 단계 *${d.worst_level}*`,
    '',
    '*조치가 필요한 처방*',
    ...d.rows.map(r =>
      `  · ${r.priority} ${r.defect_id} (${r.member_label}) — 기한 ${r.due_date ?? '차기검진'}` +
      (r.days_overdue > 0 ? ` · ${r.days_overdue}일 초과` : '') +
      (r.escalation ? ` · ${r.escalation.level} ${r.escalation.action}` : '')),
    '',
    '*유의점*',
    '  · 이행(Executed)만으로는 종결되지 않습니다. 검증(Verified)을 거쳐야 합니다 (§10.1)',
    '  · P0는 소견서 완성 여부와 무관하게 즉시 통보 대상입니다 (§9.3)',
    '',
    `*무엇부터* 최고 단계 ${d.worst_level} 항목부터 처리하십시오.`,
  ];
  return { json: { ...d, text: lines.join('\n') } };
});
